import{_ as a,o as t,c as s,a5 as i}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"Internationalization and accessibility","description":"","frontmatter":{"title":"Internationalization and accessibility","docId":"developer.i18n-accessibility","translationKey":"developer.i18n-accessibility","locale":"en","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2c74fcefd1d28353b1135c547b2e3e6ae852af8b683350011732d10c364f9323","translationRevision":"2c74fcefd1d28353b1135c547b2e3e6ae852af8b683350011732d10c364f9323","order":120},"headers":[],"relativePath":"en/developer/i18n-accessibility.md","filePath":"en/developer/i18n-accessibility.md","lastUpdated":1794611623000}'),o={name:"en/developer/i18n-accessibility.md"};function n(l,e,r,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="internationalization-and-accessibility" tabindex="-1">Internationalization and accessibility <a class="header-anchor" href="#internationalization-and-accessibility" aria-label="Permalink to &quot;Internationalization and accessibility {#internationalization-and-accessibility}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Add a screen that remains understandable in supported locales and usable by keyboard, touch and assistive technology. Read <a href="./frontend.html">frontend layers</a> and use the existing shared UI. Runtime application locales and the published documentation editions are separate systems.</p><h2 id="add-localized-content" tabindex="-1">Add localized content <a class="header-anchor" href="#add-localized-content" aria-label="Permalink to &quot;Add localized content {#add-localized-content}&quot;">​</a></h2><p>The application catalog lives in <code>src/web/shared/i18n/</code>. English is the typed fallback; All other supported catalogs load lazily. <code>activateLocale</code> loads the chosen messages and updates <code>document.documentElement.lang</code>. Store a locale preference through the existing locale store rather than writing another local-storage key.</p><ol><li>Add the semantic message key to the English catalog and equivalent supported catalogs/modules.</li><li>Keep API IDs, event paths and stored resource identifiers stable; translate their visible labels.</li><li>Use interpolation for variable text and shared internationalization helpers for display values.</li><li>For plugin descriptors, use the existing <code>{default,i18key}</code> localized text contract and host-merged catalogs. Never render translated or plugin-provided strings as HTML.</li></ol><h2 id="preserve-control-semantics" tabindex="-1">Preserve control semantics <a class="header-anchor" href="#preserve-control-semantics" aria-label="Permalink to &quot;Preserve control semantics {#preserve-control-semantics}&quot;">​</a></h2><p>Prefer <code>BaseTextField</code>, <code>BaseFormRow</code>, <code>BaseDialog</code>, tabs and status components. A placeholder does not replace an accessible label. Icon buttons need a localized name. Validation must identify the field and expose invalid state; do not communicate failure only through color. Preserve dialog focus return, Escape behavior, keyboard selection and visible focus outlines.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i18n</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> catalogs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BaseDialog</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> frontend-lint</span></span></code></pre></div><p>For manual review, tab through the complete flow, open/close the dialog, switch locale while it is open and repeat at narrow width. Status actions that reveal on hover must also reveal on keyboard focus and remain available on touch.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Catalog typing and parity checks catch missing keys; shared controls provide implemented keyboard and ARIA behavior. They do not constitute a blanket accessibility certification of every composed screen. Rankings remains hidden even if translated strings exist.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>If untranslated text appears, check lazy catalog loading and exact key spelling before adding English fallbacks in components. If focus disappears, inspect the control receiving forwarded attributes and the dialog&#39;s return target. The <a href="https://github.com/nglmercer/TikTools-app/blob/remake/src/web/shared/i18n/i18n.ts" target="_blank" rel="noreferrer">i18n implementation</a> and component tests define the current behavior; <a href="./components/">components</a> explains the shared entry points.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>Locale detection is saved <code>tiktok-live-locale</code> → <code>navigator.languages</code> → English. <code>normalizeLocale</code> handles regional tags and <code>jp</code> → <code>ja</code>. UI codes/format regions are <code>en/en-US</code>, <code>es/es-ES</code>, <code>pt/pt-BR</code>, <code>fr/fr-FR</code>, <code>zh/zh-CN</code>, <code>ja/ja-JP</code>; use <code>intl.ts</code> formatCount/formatDate. <code>activateLocale</code> loads messages and document lang; <code>useLocaleStore().setLocale</code> also persists and stages preferences best-effort. Use the store for a preference control. English is fallback; zh/ja also load host-message modules. To add a locale, update supported-locales, lazy loaders, catalog/host messages, format-region mapping, preference tests, catalog key/placeholder/plural compilation tests, and corresponding docs/site locale routing. Preserve API IDs and parameter names.</p><p>Use spacing/type/control/focus/z-layer tokens rather than fixed sizes. Any coarse pointer or viewport under 700px raises controls to 44px; layout navigation changes under 900px and form rows under 600px independently. Reduced motion zeroes durations. Test coarse pointer at desktop width too. The app is dark globally; the light token override is JSON-specific, not a global light-theme feature.</p><p>Keyboard map: tabs use arrows/Home/End with automatic selection; selects use arrows/Home/End/Enter and Escape cancellation; menus return focus to their trigger. Dialogs use native showModal focus containment, but <code>closable=false</code> blocks Escape and closing unmounts content. Keep drafts with the owner and verify initial/return focus in the composed screen. Icon buttons need <code>label</code>; <code>hint</code>/tooltip is extra explanation, never their name. Tooltips appear after 500ms on hover/focus, close with Escape and stay in the dialog top layer. Review real keyboard and assistive flows; unit tests do not certify a whole screen.</p>`,18)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
